// ============================================================================
// mini_soc_apb_subsys -- APB subsystem behind NoC port S_PERIPH,
// generated by socgen from socgen/specs/mini_soc.yaml
//   AXI4 slave -> axi2apb_bridge -> slot decoder PADDR[15:12] (16 slots of 4 KB)
//   slot  0  0x10000000  gpio             open-ip GPIO_apb

//   slot  1  0x10001000  uart             open-ip UART_apb

//   slot  2  0x10002000  ext              external APB port (VIP)

//   slot  3  0x10003000  iommu0_regs      mini_soc_iommu_regs

//   empty slots answer PSLVERR
// ============================================================================
module mini_soc_apb_subsys (
  input  logic        clk,
  input  logic        rst_n,
  // AXI4 slave (from the NoC)
  input  logic [7:0]  awid,   input  logic [31:0] awaddr, input  logic [7:0] awlen,
  input  logic [2:0]  awsize, input  logic [1:0]  awburst, input logic [2:0] awprot,
  input  logic        awvalid, output logic       awready,
  input  logic [31:0] wdata,  input  logic [3:0]  wstrb,  input  logic wlast,
  input  logic        wvalid, output logic        wready,
  output logic [7:0]  bid,    output logic [1:0]  bresp,  output logic bvalid, input logic bready,
  input  logic [7:0]  arid,   input  logic [31:0] araddr, input  logic [7:0] arlen,
  input  logic [2:0]  arsize, input  logic [1:0]  arburst, input logic [2:0] arprot,
  input  logic        arvalid, output logic       arready,
  output logic [7:0]  rid,    output logic [31:0] rdata,  output logic [1:0] rresp,
  output logic        rlast,  output logic        rvalid, input  logic rready,
  // external APB completer port: ext (slot 2)
  output logic [31:0] ext_paddr,  output logic ext_psel, output logic ext_penable,
  output logic        ext_pwrite, output logic [31:0] ext_pwdata, output logic [3:0] ext_pstrb,
  output logic [2:0]  ext_pprot,
  input  logic [31:0] ext_prdata, input logic ext_pready, input logic ext_pslverr,
  output logic [3:0] irq        // one per mapped slot, slot order (0 when the block has none)
);
  logic [31:0] paddr, pwdata, prdata;
  logic        psel, penable, pwrite, pready, pslverr;
  logic [3:0]  pstrb;
  logic [2:0]  pprot;

  axi2apb_bridge #(.IDW(8)) u_bridge (
    .clk, .rst_n,
    .awid, .awaddr, .awlen, .awsize, .awburst, .awprot, .awvalid, .awready,
    .wdata, .wstrb, .wlast, .wvalid, .wready, .bid, .bresp, .bvalid, .bready,
    .arid, .araddr, .arlen, .arsize, .arburst, .arprot, .arvalid, .arready,
    .rid, .rdata, .rresp, .rlast, .rvalid, .rready,
    .paddr, .psel, .penable, .pwrite, .pwdata, .pstrb, .pprot, .prdata, .pready, .pslverr
  );

  // ---------------- slot decode ----------------
  localparam int NMAP = 4;
  wire [3:0] slot = paddr[15:12];
  logic        s_psel    [NMAP];
  logic [31:0] s_prdata  [NMAP];
  logic        s_pready  [NMAP];
  logic        s_pslverr [NMAP];
  localparam logic [3:0] SLOT [NMAP] = '{ 0, 1, 2, 3 };
  always_comb begin
    prdata  = 32'h0;
    pready  = 1'b1;
    pslverr = psel & penable;                    // empty slot
    for (int i = 0; i < NMAP; i++) begin
      s_psel[i] = psel && (slot == SLOT[i]);
      if (slot == SLOT[i]) begin
        prdata  = s_prdata[i];
        pready  = s_pready[i];
        pslverr = s_pslverr[i];
      end
    end
  end

  // ---------------- slot 0: gpio ----------------
  tri1 [7:0] gpio_gpio;      // weak pull-up, nothing else drives it
  GPIO_apb u_gpio (
    .PCLK(clk), .PRESETN(rst_n), .PSEL(s_psel[0]), .PENABLE(penable), .PWRITE(pwrite),
    .PADDR(paddr[11:0]), .PWDATA(pwdata), .PSTRB(pstrb),
    .PRDATA(s_prdata[0]), .PREADY(s_pready[0]), .PSLVERR(s_pslverr[0]), .irq(irq[0]),
    .gpio(gpio_gpio)

  );

  // ---------------- slot 1: uart ----------------
  logic [0:0] uart_txd;
  UART_apb u_uart (
    .PCLK(clk), .PRESETN(rst_n), .PSEL(s_psel[1]), .PENABLE(penable), .PWRITE(pwrite),
    .PADDR(paddr[11:0]), .PWDATA(pwdata), .PSTRB(pstrb),
    .PRDATA(s_prdata[1]), .PREADY(s_pready[1]), .PSLVERR(s_pslverr[1]), .irq(irq[1]),
    .rxd(1'b1),
    .txd(uart_txd)

  );

  // ---------------- slot 2: ext ----------------
  assign ext_paddr   = paddr;
  assign ext_psel    = s_psel[2];
  assign ext_penable = penable & s_psel[2];
  assign ext_pwrite  = pwrite;
  assign ext_pwdata  = pwdata;
  assign ext_pstrb   = pstrb;
  assign ext_pprot   = pprot;
  assign s_prdata[2]  = ext_prdata;
  assign s_pready[2]  = ext_pready;
  assign s_pslverr[2] = ext_pslverr;
  assign irq[2] = 1'b0;

  // ---------------- slot 3: iommu0_regs ----------------
  mini_soc_iommu_regs u_iommu0_regs (
    .PCLK(clk), .PRESETN(rst_n), .PSEL(s_psel[3]), .PENABLE(penable), .PWRITE(pwrite),
    .PADDR(paddr[11:0]), .PWDATA(pwdata), .PSTRB(pstrb),
    .PRDATA(s_prdata[3]), .PREADY(s_pready[3]), .PSLVERR(s_pslverr[3]),
    .hw_fault(32'h0),
    .q_ctrl(),
    .q_pt_base(),
    .q_scratch()

  );
  assign irq[3] = 1'b0;

endmodule
